    ////////////////////////////////////////////
    // IExchangeOutgoingServer implementation //
    ////////////////////////////////////////////

    xpcom_method!(set_exchange_url => SetExchangeUrl(endpoint_url: *const nsACString));
    fn set_exchange_url(&self, endpoint_url: &nsACString) -> Result<(), nsresult> {
        let key = self.key()?;

        log::debug!("Creating new outgoing server for {endpoint_url} ({key})");
        let url = endpoint_url.to_string();
        let url = Url::parse(url.as_str()).or(Err(nserror::NS_ERROR_FAILURE))?;

        self.endpoint_url
            .set(url)
            .or(Err(nserror::NS_ERROR_ALREADY_INITIALIZED))?;

        self.store_string_pref(PrefName::EwsUrl, endpoint_url)
    }

    xpcom_method!(exchange_url => GetExchangeUrl() -> nsACString);
    fn exchange_url(&self) -> Result<nsCString, nsresult> {
        let url = self.endpoint_url()?;
        Ok(nsCString::from(url.to_string()))
    }
}
